                  <button onClick={handleHistoryClear} style={{ background: "none", border: `1px solid ${Z.border}`, borderRadius: 5, padding: "0 12px", height: 30, fontSize: 12, color: Z.text2, cursor: "pointer" }}>Clear</button>
