function ReportsView({
  emps,
  ss,
  payruns,
}: {
  emps: Employee[];
  ss: SalaryStructure[];
  payruns: Payrun[];
}) {
  const toast = useToast();
  const orgName = "Naxrita Solutions Pvt. Ltd.";
  const depts = Array.from(
    new Set(emps.map((e) => e.department).filter(Boolean)),
  ).sort();
  const latestPaid = payruns
    .filter((p) => isFinalizedPayrun(p.status))
    .sort((a, b) => (a.year !== b.year ? a.year - b.year : a.month - b.month))
    .pop();

  const makeFilters = (kind: RptFilterKind): RptFilters => ({
    month: latestPaid?.period ?? RPT_MONTHS[6],
    range: "Current Financial Year",
    criteria:
      kind === "none"
        ? []
        : [{ id: 1, field: "Payroll Status", op: "is", value: "Paid" }],
  });

  const [section, setSection] = useState("home");
  const [search, setSearch] = useState("");
  const [favorites, setFavorites] = useState<string[]>([]);
  const [lastVisited, setLastVisited] = useState<Record<string, string>>({});
  const [activeId, setActiveId] = useState<string | null>(null);
  const [draft, setDraft] = useState<RptFilters>(makeFilters("month"));
  const [applied, setApplied] = useState<RptFilters>(makeFilters("month"));
  const [showMore, setShowMore] = useState(false);
  const [groupBy, setGroupBy] = useState("none");
  const [hiddenCols, setHiddenCols] = useState<number[]>([]);
  const [showCols, setShowCols] = useState(false);
  const [showExport, setShowExport] = useState(false);
  const [scheduleReport, setScheduleReport] = useState<RptDef | null>(null);
  const [scheduledReports, setScheduledReports] = useState<
    Array<{
      id: string;
      reportId: string;
      name: string;
      category: string;
      frequency: string;
      startDate: string;
      time: string;
      recipients: string;
      format: string;
    }>
  >([]);
  const [scheduleFrequency, setScheduleFrequency] = useState("Weekly");
  const [scheduleDate, setScheduleDate] = useState(
    new Date().toISOString().slice(0, 10),
  );
  const [scheduleHour, setScheduleHour] = useState("11");
  const [scheduleMinute, setScheduleMinute] = useState("30");
  const [scheduleRecipients, setScheduleRecipients] = useState("");
  const [scheduleAdditional, setScheduleAdditional] = useState("");
  const [scheduleFormat, setScheduleFormat] = useState("PDF");

  const def = REPORTS.find((r) => r.id === activeId) ?? null;

  const openReport = (r: RptDef) => {
    const f = makeFilters(r.filter);
    setActiveId(r.id);
    setDraft(f);
    setApplied(f);
    setShowMore(false);
    setShowCols(false);
    setShowExport(false);
    setGroupBy("none");
    setHiddenCols([]);
    const stamp = new Date()
      .toLocaleString("en-GB", {
        day: "2-digit",
        month: "2-digit",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit",
        hour12: true,
      })
      .replace(",", "")
      .toUpperCase();
    setLastVisited((prev) => ({ ...prev, [r.id]: stamp }));
    document.querySelector("main")?.scrollTo({ top: 0 });
  };
  const closeReport = () => setActiveId(null);
  const toggleFavorite = (id: string) =>
    setFavorites((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id],
    );

  // ── criteria helpers ──
  const criteriaFields =
    def?.filter === "none"
      ? ["Department", "Employee Type"]
      : ["Payroll Status", "Department", "Employee Type"];
  const valuesFor = (field: string) =>
    field === "Payroll Status"
      ? ["Paid", "Unpaid"]
      : field === "Department"
        ? depts
        : ["Full-Time", "Part-Time", "Contract"];
  const addCriteria = () =>
    setDraft((d) => ({
      ...d,
      criteria: [
        ...d.criteria,
        {
          id: Date.now(),
          field: criteriaFields[0],
          op: "is",
          value: valuesFor(criteriaFields[0])[0] ?? "",
        },
      ],
    }));
  const updateCriteria = (id: number, patch: Partial<RptCriteria>) =>
    setDraft((d) => ({
      ...d,
      criteria: d.criteria.map((c) =>
        c.id === id
          ? {
              ...c,
              ...patch,
              ...(patch.field
                ? { value: valuesFor(patch.field)[0] ?? "" }
                : {}),
            }
          : c,
      ),
    }));
  const removeCriteria = (id: number) =>
    setDraft((d) => ({
      ...d,
      criteria: d.criteria.filter((c) => c.id !== id),
    }));
  const runNow = () => {
    setApplied(draft);
    setShowMore(false);
    toast(`${def?.name ?? "Report"} generated`, "success");
  };
  const cancelMore = () => {
    setDraft(applied);
    setShowMore(false);
  };

  // ── run the report ──
  const runReport = (r: RptDef): RptResult => {
    const f = applied;
    const statusCrit = f.criteria.find(
      (c) => c.field === "Payroll Status" && c.value,
    );
    const empOk = (e: Employee) =>
      f.criteria.every((c) => {
        if (!c.value) return true;
        if (c.field === "Department")
          return c.op === "is"
            ? e.department === c.value
            : e.department !== c.value;
        if (c.field === "Employee Type")
          return c.op === "is" ? e.empType === c.value : e.empType !== c.value;
        return true;
      });
    const periodRuns = payruns.filter((run) =>
      r.filter === "month"
        ? run.period === f.month
        : r.filter === "range"
          ? rptRunInRange(run, f.range)
          : false,
    );
    const scoped = periodRuns.filter((run) => {
      if (!statusCrit) return true;
      const paid = isFinalizedPayrun(run.status);
      const match = statusCrit.value === "Paid" ? paid : !paid;
      return statusCrit.op === "is" ? match : !match;
    });
    const items: RptItem[] = scoped
      .flatMap((run) =>
        run.rows.map((row) => ({
          run,
          row,
          emp: emps.find((e) => e.id === row.empId),
        })),
      )
      .filter((i) => (i.emp ? empOk(i.emp) : true));
    const emptyMsg =
      statusCrit && statusCrit.value === "Paid" && statusCrit.op === "is"
        ? "You haven't paid any employees in this period."
        : "There are no payroll records for this period.";
    if (r.filter !== "none" && !r.handlesEmpty && items.length === 0) {
      return { type: "message", text: emptyMsg };
    }
    return r.build({ items, emps: emps.filter(empOk), ss });
  };
  const result: RptResult | null = def ? runReport(def) : null;

  // ── table view helpers ──
  const isNumCol = (c: RptCol) => c.kind === "money" || c.kind === "num";
  const cell = (c: RptCol, v: string | number) =>
    v === ""
      ? "—"
      : c.kind === "money" && typeof v === "number"
        ? inr(v)
        : String(v);
  const buildTableView = (res: Extract<RptResult, { type: "table" }>) => {
    const vis = res.cols
      .map((_, i) => i)
      .filter((i) => !hiddenCols.includes(i));
    const grouped = groupBy !== "none" && res.groupCol !== undefined;
    const gc = res.groupCol ?? 0;
    const rows = grouped
      ? [...res.rows].sort((a, b) => String(a[gc]).localeCompare(String(b[gc])))
      : res.rows;
    const totals = vis.map((i) =>
      res.cols[i].total
        ? rows.reduce(
            (s, r) => s + (typeof r[i] === "number" ? (r[i] as number) : 0),
            0,
          )
        : null,
    );
    return { vis, rows, grouped, gc, totals };
  };

  const periodText = () => {
    if (!def) return "";
    if (def.filter === "month") return applied.month.replace(" ", ", ");
    if (def.filter === "range") {
      const b = rptBounds(applied.range);
      return b ? `From ${rptDate(b.s)} To ${rptDate(b.e)}` : "All Time";
    }
    return `As of ${rptDate(new Date())}`;
  };

  // ── export ──
  const csvEscape = (v: unknown) => {
    const t = String(v ?? "");
    return /[",\n]/.test(t) ? `"${t.replace(/"/g, '""')}"` : t;
  };
  const exportCsv = () => {
    if (!def || !result) return;
    let data: (string | number)[][] = [];
    if (result.type === "table") {
      const v = buildTableView(result);
      data = [
        v.vis.map((i) => result.cols[i].label),
        ...v.rows.map((r) => v.vis.map((i) => r[i])),
      ];
    } else if (result.type === "summary") {
      data = [
        ["Metric", "Value"],
        ...result.cards.map((c) => [c.label, c.value]),
        ...(result.list ?? []),
      ];
    } else {
      toast("This report has no data to export", "warning");
      return;
    }
    const csv = data.map((r) => r.map(csvEscape).join(",")).join("\n");
    const url = URL.createObjectURL(
      new Blob([csv], { type: "text/csv;charset=utf-8;" }),
    );
    const a = document.createElement("a");
    a.href = url;
    a.download = `${def.name.replace(/[^a-z0-9]+/gi, "_")}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    setShowExport(false);
    toast(`${def.name} exported as CSV`, "success");
  };
  const exportPdf = () => {
    if (!def || !result) return;
    if (result.type === "message") {
      toast("This report has no data to export", "warning");
      return;
    }
    const w = window.open("", "_blank", "width=900,height=1000");
    if (!w) return;
    const esc = (s: unknown) =>
      String(s)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
    let body = "";
    if (result.type === "table") {
      const v = buildTableView(result);
      body = `<table><thead><tr>${v.vis.map((i) => `<th>${esc(result.cols[i].label)}</th>`).join("")}</tr></thead><tbody>${v.rows
        .map(
          (r) =>
            `<tr>${v.vis.map((i) => `<td>${esc(cell(result.cols[i], r[i]))}</td>`).join("")}</tr>`,
        )
        .join("")}</tbody></table>`;
    } else {
      body = `<table><tbody>${[
        ...result.cards.map((c) => [c.label, c.value]),
        ...(result.list ?? []),
      ]
        .map((r) => `<tr><td>${esc(r[0])}</td><td>${esc(r[1])}</td></tr>`)
        .join("")}</tbody></table>`;
    }
    w.document.write(`<html><head><title>${esc(def.name)}</title><style>
      body{font-family:Arial,sans-serif;padding:28px;color:#1D2D3E}
      h1,h2,p{text-align:center;margin:4px 0} table{width:100%;border-collapse:collapse;margin-top:18px;font-size:12px}
      th,td{border:1px solid #D5DADD;padding:7px 9px;text-align:left} th{background:#F5F6F7;text-transform:uppercase;font-size:11px}
    </style></head><body><p>${esc(orgName)}</p><h2>${esc(def.name)}</h2><p>${esc(periodText())}</p>${body}
    <script>window.onload=function(){window.print()}</script></body></html>`);
    w.document.close();
    setShowExport(false);
  };

  // ═════════════ REPORT VIEW ═════════════
  if (def && result) {
    const chip: React.CSSProperties = {
      display: "inline-flex",
      alignItems: "center",
      gap: 6,
      border: "none",
      borderRadius: 6,
      padding: "5px 10px",
      fontSize: 12,
      color: F.text2,
      background: "transparent",
      height: 32,
      boxSizing: "border-box",
    };
    const bareSelect: React.CSSProperties = {
      border: "none",
      outline: "none",
      background: "transparent",
      fontSize: 12,
      fontWeight: 700,
      color: F.text1,
      fontFamily: "inherit",
      cursor: "pointer",
    };
    const tv = result.type === "table" ? buildTableView(result) : null;

    return (
      <>
        {scheduleReport && (
          <div
            role="presentation"
            onMouseDown={(e) => {
              if (e.target === e.currentTarget) setScheduleReport(null);
            }}
            style={{
              position: "fixed",
              inset: 0,
              zIndex: 1000,
              background: "rgba(15,23,42,0.48)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              padding: 20,
            }}
          >
            <section
              role="dialog"
              aria-modal="true"
              aria-label="Schedule Report"
              style={{
                width: "min(560px, 100%)",
                maxHeight: "90vh",
                overflowY: "auto",
                background: F.card,
                borderRadius: 8,
                boxShadow: "0 16px 48px rgba(15,23,42,0.25)",
              }}
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "flex-start",
                  padding: "20px 22px 14px",
                  borderBottom: `1px solid ${F.border}`,
                }}
              >
                <div>
                  <h2 style={{ margin: 0, fontSize: 19, color: F.text1 }}>
                    Schedule Report
                  </h2>
                  <div style={{ marginTop: 5, fontSize: 12, color: F.text2 }}>
                    Report Name: {scheduleReport.name}
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => setScheduleReport(null)}
                  aria-label="Close schedule report"
                  style={{
                    border: 0,
                    background: "transparent",
                    color: F.text3,
                    fontSize: 22,
                    cursor: "pointer",
                  }}
                >
                  ×
                </button>
              </div>
              <form
                onSubmit={(e) => {
                  e.preventDefault();
                  const recipients = [
                    scheduleRecipients,
                    ...scheduleAdditional.split(","),
                  ]
                    .map((email) => email.trim())
                    .filter(Boolean);
                  if (!scheduleReport || !recipients.length) {
                    toast("Enter at least one email recipient.", "error");
                    return;
                  }
                  const hour = Math.min(
                    12,
                    Math.max(1, Number(scheduleHour) || 1),
                  );
                  const minute = String(
                    Math.min(59, Math.max(0, Number(scheduleMinute) || 0)),
                  ).padStart(2, "0");
                  setScheduledReports((prev) => [
                    {
                      id: `${scheduleReport.id}-${Date.now()}`,
                      reportId: scheduleReport.id,
                      name: scheduleReport.name,
                      category: scheduleReport.category,
                      frequency: scheduleFrequency,
                      startDate: scheduleDate,
                      time: `${String(hour).padStart(2, "0")}:${minute}`,
                      recipients: recipients.join(", "),
                      format: scheduleFormat,
                    },
                    ...prev,
                  ]);
                  toast(
                    `${scheduleReport.name} scheduled ${scheduleFrequency.toLowerCase()} as ${scheduleFormat}.`,
                    "success",
                  );
                  setScheduleReport(null);
                }}
                style={{ padding: "18px 22px 22px" }}
              >
                <label
                  style={{
                    display: "block",
                    fontSize: 12,
                    fontWeight: 700,
                    color: F.text2,
                    marginBottom: 14,
                  }}
                >
                  Frequency <span style={{ color: F.error }}>*</span>
                  <select
                    required
                    value={scheduleFrequency}
                    onChange={(e) => setScheduleFrequency(e.target.value)}
                    style={{ ...iSt, display: "block", marginTop: 6 }}
                  >
                    <option>Daily</option>
                    <option>Weekly</option>
                    <option>Monthly</option>
                    <option>Quarterly</option>
                  </select>
                </label>
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "minmax(0,1fr) 90px 90px",
                    gap: 10,
                    marginBottom: 18,
                  }}
                >
                  <label
                    style={{ fontSize: 12, fontWeight: 700, color: F.text2 }}
                  >
                    Start Date <span style={{ color: F.error }}>*</span>
                    <input
                      required
                      type="date"
                      value={scheduleDate}
                      onChange={(e) => setScheduleDate(e.target.value)}
                      style={{ ...iSt, display: "block", marginTop: 6 }}
                    />
                  </label>
                  <label
                    style={{ fontSize: 12, fontWeight: 700, color: F.text2 }}
                  >
                    Hour
                    <input
                      type="number"
                      min="1"
                      max="12"
                      required
                      value={scheduleHour}
                      onChange={(e) => setScheduleHour(e.target.value)}
                      style={{ ...iSt, display: "block", marginTop: 6 }}
                    />
                  </label>
                  <label
                    style={{ fontSize: 12, fontWeight: 700, color: F.text2 }}
                  >
                    Minutes
                    <input
                      type="number"
                      min="0"
                      max="59"
                      required
                      value={scheduleMinute}
                      onChange={(e) => setScheduleMinute(e.target.value)}
                      style={{ ...iSt, display: "block", marginTop: 6 }}
                    />
                  </label>
                </div>
                <div
                  style={{
                    borderTop: `1px solid ${F.border}`,
                    paddingTop: 16,
                    marginBottom: 14,
                    fontSize: 13,
                    fontWeight: 800,
                    color: F.text1,
                  }}
                >
                  Recipient Details
                </div>
                <label
                  style={{
                    display: "block",
                    fontSize: 12,
                    fontWeight: 700,
                    color: F.text2,
                    marginBottom: 12,
                  }}
                >
                  Email Recipients <span style={{ color: F.error }}>*</span>
                  <input
                    required
                    type="email"
                    placeholder="name@company.com"
                    value={scheduleRecipients}
                    onChange={(e) => setScheduleRecipients(e.target.value)}
                    style={{ ...iSt, display: "block", marginTop: 6 }}
                  />
                </label>
                <label
                  style={{
                    display: "block",
                    fontSize: 12,
                    fontWeight: 700,
                    color: F.text2,
                    marginBottom: 16,
                  }}
                >
                  Additional Recipients
                  <input
                    type="text"
                    placeholder="Separate multiple email addresses with commas"
                    value={scheduleAdditional}
                    onChange={(e) => setScheduleAdditional(e.target.value)}
                    style={{ ...iSt, display: "block", marginTop: 6 }}
                  />
                </label>
                <fieldset style={{ border: 0, padding: 0, margin: "0 0 20px" }}>
                  <legend
                    style={{
                      fontSize: 12,
                      fontWeight: 700,
                      color: F.text2,
                      marginBottom: 8,
                    }}
                  >
                    Attach Report <span style={{ color: F.error }}>*</span>
                  </legend>
                  {[
                    "PDF",
                    "XLS (Microsoft Excel 1997-2004 Compatible)",
                    "XLSX (Microsoft Excel)",
                  ].map((format) => (
                    <label
                      key={format}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 8,
                        fontSize: 12,
                        margin: "7px 0",
                        color: F.text1,
                      }}
                    >
                      <input
                        type="radio"
                        name="scheduleFormat"
                        checked={scheduleFormat === format.split(" ")[0]}
                        onChange={() => setScheduleFormat(format.split(" ")[0])}
                      />
                      {format}
                    </label>
                  ))}
                </fieldset>
                <div
                  style={{
                    background: F.infoBg,
                    borderRadius: 6,
                    padding: 12,
                    fontSize: 11,
                    color: F.text2,
                    marginBottom: 18,
                  }}
                >
                  Note: The scheduled report uses the access permissions of the
                  user who schedules it. Generated reports may be limited by
                  system record limits.
                </div>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "flex-end",
                    gap: 8,
                  }}
                >
                  <Btn
                    variant="secondary"
                    onClick={() => setScheduleReport(null)}
                  >
                    Cancel
                  </Btn>
                  <button
                    type="submit"
                    style={{
                      border: 0,
                      borderRadius: 5,
                      background: F.brand,
                      color: "#fff",
                      padding: "9px 16px",
                      fontWeight: 700,
                      cursor: "pointer",
                    }}
                  >
                    Schedule
                  </button>
                </div>
              </form>
            </section>
          </div>
        )}
        <div
          style={{
            background: F.card,
            border: `1px solid ${F.border}`,
            borderRadius: 8,
            marginTop: 16,
            minHeight: 540,
            boxShadow: "0 1px 4px rgba(15,23,42,0.06)",
          }}
        >
          {/* Header */}
          <div
            style={{
              padding: "14px 20px",
              display: "flex",
              alignItems: "center",
              gap: 12,
              flexWrap: "wrap",
              borderBottom: `1px solid ${F.border}`,
            }}
          >
            <div style={{ flex: 1, minWidth: 240 }}>
              <div style={{ fontSize: 11, color: F.text3 }}>{def.category}</div>
              <div style={{ fontSize: 18, fontWeight: 800, color: F.text1 }}>
                {def.name}{" "}
                <span style={{ fontSize: 12, fontWeight: 500, color: F.text2 }}>
                  • {periodText()}
                </span>
              </div>
            </div>
            <button
              type="button"
              title={`Schedule ${def.name}`}
              aria-label={`Schedule ${def.name}`}
              onClick={() => {
                setScheduleReport(def);
                setScheduleFrequency("Weekly");
                setScheduleDate(new Date().toISOString().slice(0, 10));
                setScheduleHour("11");
                setScheduleMinute("30");
                setScheduleRecipients("");
                setScheduleAdditional("");
                setScheduleFormat("PDF");
              }}
              style={{
                border: "1px solid #C7DDF8",
                background: "#F0F7FF",
                color: F.brand,
                borderRadius: 5,
                padding: "7px 10px",
                cursor: "pointer",
                fontSize: 16,
                lineHeight: 1,
              }}
            >
              ◷
            </button>
            <div style={{ position: "relative" }}>
              <Btn variant="secondary" onClick={() => setShowExport((v) => !v)}>
                Export as ▾
              </Btn>
              {showExport && (
                <>
                  <div
                    style={{ position: "fixed", inset: 0, zIndex: 20 }}
                    onClick={() => setShowExport(false)}
                  />
                  <div
                    style={{
                      position: "absolute",
                      right: 0,
                      top: 40,
                      zIndex: 21,
                      minWidth: 150,
                      background: F.card,
                      border: `1px solid ${F.border}`,
                      borderRadius: 6,
                      boxShadow: "0 8px 24px rgba(15,23,42,0.16)",
                      overflow: "hidden",
                    }}
                  >
                    {[
                      ["CSV", exportCsv],
                      ["PDF (Print)", exportPdf],
                    ].map(([label, fn]) => (
                      <button
                        key={label as string}
                        onClick={fn as () => void}
                        style={{
                          display: "block",
                          width: "100%",
                          textAlign: "left",
                          padding: "9px 14px",
                          border: "none",
                          background: "transparent",
                          cursor: "pointer",
                          fontSize: 13,
                          fontFamily: "inherit",
                          color: F.text1,
                        }}
                        onMouseEnter={(e) =>
                          (e.currentTarget.style.background = F.highlight)
                        }
                        onMouseLeave={(e) =>
                          (e.currentTarget.style.background = "transparent")
                        }
                      >
                        {label as string}
                      </button>
                    ))}
                  </div>
                </>
              )}
            </div>
            <button
              onClick={closeReport}
              title="Close report"
              aria-label="Close report"
              style={{
                border: "none",
                background: "transparent",
                color: F.error,
                fontSize: 20,
                cursor: "pointer",
                lineHeight: 1,
              }}
            >
              ✕
            </button>
          </div>

          {/* Filter bar */}
          <div
            style={{
              padding: "12px 20px",
              display: "flex",
              alignItems: "center",
              gap: 10,
              flexWrap: "wrap",
            }}
          >
            <span style={{ fontSize: 12, color: F.text2, fontWeight: 700 }}>
              ▽ Filters :
            </span>
            {def.filter === "month" && (
              <label style={chip}>
                Month:
                <select
                  value={draft.month}
                  onChange={(e) =>
                    setDraft({ ...draft, month: e.target.value })
                  }
                  style={bareSelect}
                >
                  {RPT_MONTHS.map((m) => (
                    <option key={m}>{m}</option>
                  ))}
                </select>
              </label>
            )}
            {def.filter === "range" && (
              <label style={chip}>
                Date Range:
                <select
                  value={draft.range}
                  onChange={(e) =>
                    setDraft({ ...draft, range: e.target.value })
                  }
                  style={bareSelect}
                >
                  {RPT_RANGES.map((m) => (
                    <option key={m}>{m}</option>
                  ))}
                </select>
              </label>
            )}
            <button
              onClick={() => setShowMore((v) => !v)}
              style={{
                ...chip,
                cursor: "pointer",
                color: F.brand,
                fontWeight: 700,
                fontFamily: "inherit",
                background: showMore ? F.infoBg : F.card,
              }}
            >
              ✚ More Filters
              {draft.criteria.length > 0 ? ` (${draft.criteria.length})` : ""}
            </button>
            {!showMore && (
              <Btn variant="success" style={{ height: 32 }} onClick={runNow}>
                Run Report
              </Btn>
            )}
          </div>

          {/* More filters / criteria */}
          {showMore && (
            <div
              style={{
                margin: "0 20px 14px",
                border: `1px solid ${F.border}`,
                borderRadius: 8,
                padding: "16px 18px",
                background: "#FBFCFD",
              }}
            >
              {draft.criteria.map((c, idx) => (
                <div
                  key={c.id}
                  style={{
                    display: "grid",
                    gridTemplateColumns: "24px 1.1fr 0.8fr 1.6fr 24px",
                    gap: 10,
                    alignItems: "center",
                    marginBottom: 10,
                  }}
                >
                  <span style={{ fontSize: 12, color: F.text3 }}>
                    {idx + 1}
                  </span>
                  <select
                    value={c.field}
                    onChange={(e) =>
                      updateCriteria(c.id, { field: e.target.value })
                    }
                    style={iSt}
                  >
                    {criteriaFields.map((f) => (
                      <option key={f}>{f}</option>
                    ))}
                  </select>
                  <select
                    value={c.op}
                    onChange={(e) =>
                      updateCriteria(c.id, {
                        op: e.target.value as RptCriteria["op"],
                      })
                    }
                    style={iSt}
                  >
                    <option>is</option>
                    <option>is not</option>
                  </select>
                  <select
                    value={c.value}
                    onChange={(e) =>
                      updateCriteria(c.id, { value: e.target.value })
                    }
                    style={iSt}
                  >
                    {valuesFor(c.field).map((v) => (
                      <option key={v}>{v}</option>
                    ))}
                  </select>
                  <button
                    onClick={() => removeCriteria(c.id)}
                    title="Remove criteria"
                    style={{
                      border: "none",
                      background: "transparent",
                      color: F.text3,
                      cursor: "pointer",
                      fontSize: 16,
                    }}
                  >
                    🗑
                  </button>
                </div>
              ))}
              <button
                onClick={addCriteria}
                style={{
                  border: "none",
                  background: "transparent",
                  color: F.brand,
                  cursor: "pointer",
                  fontWeight: 700,
                  fontSize: 12,
                  fontFamily: "inherit",
                  padding: 0,
                }}
              >
                ⊕ Add Criteria
              </button>
              <div style={{ display: "flex", gap: 8, marginTop: 18 }}>
                <Btn variant="success" onClick={runNow}>
                  Run Report
                </Btn>
                <Btn variant="secondary" onClick={cancelMore}>
                  Cancel
                </Btn>
              </div>
            </div>
          )}

          {/* Report body */}
          <div
            style={{
              margin: "0 20px 20px",
              border: `1px solid ${F.border}`,
              borderRadius: 8,
              background: F.card,
            }}
          >
            {tv && result.type === "table" && (
              <div
                style={{
                  display: "flex",
                  justifyContent: "flex-end",
                  alignItems: "center",
                  gap: 14,
                  padding: "10px 14px",
                  position: "relative",
                }}
              >
                {result.groupCol !== undefined && (
                  <label
                    style={{
                      fontSize: 12,
                      color: F.text2,
                      display: "flex",
                      alignItems: "center",
                      gap: 6,
                    }}
                  >
                    Group By :
                    <select
                      value={groupBy}
                      onChange={(e) => setGroupBy(e.target.value)}
                      style={{ ...bareSelect, color: F.brand }}
                    >
                      <option value="none">None</option>
                      <option value="group">{result.groupLabel}</option>
                    </select>
                  </label>
                )}
                <button
                  onClick={() => setShowCols((v) => !v)}
                  style={{
                    border: "none",
                    background: "transparent",
                    color: F.text1,
                    fontSize: 12,
                    fontWeight: 600,
                    cursor: "pointer",
                    fontFamily: "inherit",
                    display: "flex",
                    alignItems: "center",
                    gap: 6,
                  }}
                >
                  ☷ Customize Report Columns
                  <span
                    style={{
                      background: F.infoBg,
                      color: F.brand,
                      borderRadius: 8,
                      padding: "0 6px",
                      fontSize: 10,
                      fontWeight: 800,
                    }}
                  >
                    {tv.vis.length}
                  </span>
                </button>
                {showCols && (
                  <>
                    <div
                      style={{ position: "fixed", inset: 0, zIndex: 20 }}
                      onClick={() => setShowCols(false)}
                    />
                    <div
                      style={{
                        position: "absolute",
                        right: 10,
                        top: 42,
                        zIndex: 21,
                        width: 260,
                        maxHeight: 320,
                        overflowY: "auto",
                        background: F.card,
                        border: `1px solid ${F.border}`,
                        borderRadius: 8,
                        padding: 10,
                        boxShadow: "0 8px 24px rgba(15,23,42,0.18)",
                      }}
                    >
                      <div
                        style={{
                          fontSize: 12,
                          fontWeight: 800,
                          marginBottom: 8,
                        }}
                      >
                        Show / hide columns
                      </div>
                      {result.cols.map((c, i) => (
                        <label
                          key={c.label}
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: 8,
                            padding: "6px 2px",
                            fontSize: 12,
                            cursor: "pointer",
                          }}
                        >
                          <input
                            type="checkbox"
                            checked={!hiddenCols.includes(i)}
                            onChange={() => {
                              if (!hiddenCols.includes(i)) {
                                if (tv.vis.length <= 1) return;
                                setHiddenCols([...hiddenCols, i]);
                              } else
                                setHiddenCols(
                                  hiddenCols.filter((x) => x !== i),
                                );
                            }}
                          />
                          {c.label}
                        </label>
                      ))}
                      <div style={{ marginTop: 8, textAlign: "right" }}>
                        <Btn
                          small
                          variant="secondary"
                          onClick={() => setHiddenCols([])}
                        >
                          Reset
                        </Btn>
                      </div>
                    </div>
                  </>
                )}
              </div>
            )}

            <div
              style={{
                textAlign: "center",
                padding: tv ? "10px 16px 16px" : "26px 16px 16px",
              }}
            >
              <div style={{ fontSize: 12, color: F.text2 }}>{orgName}</div>
              <div
                style={{
                  fontSize: 16,
                  fontWeight: 800,
                  color: F.text1,
                  marginTop: 4,
                }}
              >
                {def.name}
              </div>
              <div style={{ fontSize: 12, color: F.text3, marginTop: 2 }}>
                {periodText()}
              </div>
            </div>

            {/* TABLE — only for reports that are genuinely tabular */}
            {result.type === "table" && tv && (
              <>
                {(tv.rows.length > 0 || result.headersWhenEmpty) && (
                  <div style={{ overflowX: "auto" }}>
                    <table
                      style={{ width: "100%", borderCollapse: "collapse" }}
                    >
                      <thead>
                        <tr>
                          {tv.vis.map((i) => (
                            <Th key={i} right={isNumCol(result.cols[i])}>
                              {result.cols[i].label}
                            </Th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {tv.rows.map((r, ri) => {
                          const prev = ri > 0 ? tv.rows[ri - 1] : null;
                          const newGroup =
                            tv.grouped &&
                            (!prev || String(prev[tv.gc]) !== String(r[tv.gc]));
                          return (
                            <Fragment key={ri}>
                              {newGroup && (
                                <tr>
                                  <td
                                    colSpan={tv.vis.length}
                                    style={{
                                      padding: "8px 14px",
                                      background: F.infoBg,
                                      color: F.brand,
                                      fontWeight: 800,
                                      fontSize: 12,
                                    }}
                                  >
                                    {result.groupLabel}: {String(r[tv.gc])} (
                                    {
                                      tv.rows.filter(
                                        (x) =>
                                          String(x[tv.gc]) === String(r[tv.gc]),
                                      ).length
                                    }
                                    )
                                  </td>
                                </tr>
                              )}
                              <TrH>
                                {tv.vis.map((i) => (
                                  <Td key={i} right={isNumCol(result.cols[i])}>
                                    {cell(result.cols[i], r[i])}
                                  </Td>
                                ))}
                              </TrH>
                            </Fragment>
                          );
                        })}
                      </tbody>
                      {tv.rows.length > 0 &&
                        tv.totals.some((t) => t !== null) && (
                          <tfoot>
                            <tr
                              style={{
                                background: F.pageBg,
                                borderTop: `2px solid ${F.border}`,
                                fontWeight: 800,
                              }}
                            >
                              {tv.vis.map((i, k) => (
                                <Td
                                  key={i}
                                  right={isNumCol(result.cols[i])}
                                  style={{ fontWeight: 800 }}
                                >
                                  {k === 0
                                    ? "Total"
                                    : tv.totals[k] !== null
                                      ? result.cols[i].kind === "money"
                                        ? inr(tv.totals[k] as number)
                                        : String(tv.totals[k])
                                      : ""}
                                </Td>
                              ))}
                            </tr>
                          </tfoot>
                        )}
                    </table>
                  </div>
                )}
                {tv.rows.length === 0 && (
                  <div
                    style={{
                      padding: "44px 16px 70px",
                      textAlign: "center",
                      fontSize: 12.5,
                      color: F.text2,
                    }}
                  >
                    {result.emptyText ?? "There is no data for this period."}
                  </div>
                )}
              </>
            )}

            {/* SUMMARY — cards and key figures, no table */}
            {result.type === "summary" && (
              <div style={{ padding: "4px 20px 28px" }}>
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "repeat(auto-fit, minmax(190px, 1fr))",
                    gap: 12,
                    marginBottom: 18,
                  }}
                >
                  {result.cards.map((c) => (
                    <Tile
                      key={c.label}
                      label={c.label}
                      value={c.value}
                      sub={c.sub}
                      accent={c.color}
                    />
                  ))}
                </div>
                {result.list && (
                  <div style={{ maxWidth: 620, margin: "0 auto" }}>
                    {result.list.map(([l, v]) => (
                      <IR key={l} label={l} value={v} />
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* MESSAGE — empty / not applicable */}
            {result.type === "message" && (
              <div
                style={{
                  padding: "44px 16px 80px",
                  textAlign: "center",
                  fontSize: 12.5,
                  color: F.text2,
                }}
              >
                {result.text}
              </div>
            )}
          </div>
        </div>
      </>
    );
  }

  // ═════════════ REPORTS CENTRE (list) ═════════════
  const searching = activeSearch(search);
  const catalog = REPORTS.filter((r) =>
    searching
      ? searchMatches(search, [r.name, r.category])
      : section === "home"
        ? true
        : section === "favorites"
          ? favorites.includes(r.id)
          : RPT_CATEGORIES.includes(section)
            ? r.category === section
            : false,
  );
  const pagedCatalog = catalog;
  const listTitle = searching
    ? "Search Results"
    : section === "home"
      ? "All Reports"
      : section === "favorites"
        ? "Favorites"
        : section === "shared"
          ? "Shared Reports"
          : section === "scheduled"
            ? "Scheduled Reports"
            : section;

  const goSection = (s: string) => {
    setSection(s);
    setSearch("");
  };

  const emptyState = (title: string, sub: string) => (
    <div style={{ padding: "70px 20px 90px", textAlign: "center" }}>
      <div
        style={{
          width: 64,
          height: 64,
          margin: "0 auto 14px",
          borderRadius: 14,
          background: F.infoBg,
          border: `1px solid ${F.brand}30`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: 28,
          color: F.brand,
        }}
      >
        ▤
      </div>
      <div style={{ fontSize: 12.5, color: F.text2 }}>{title}</div>
      <div style={{ fontSize: 12, color: F.text3, marginTop: 3 }}>{sub}</div>
    </div>
  );

  const sideItem = (id: string, label: string, icon: string) => {
    const active = !searching && section === id;
    return (
      <button
        key={id}
        onClick={() => goSection(id)}
        style={{
          display: "flex",
          alignItems: "center",
          gap: 10,
          width: "100%",
          textAlign: "left",
          padding: "9px 12px",
          border: "none",
          borderRadius: 6,
          cursor: "pointer",
          fontFamily: "inherit",
          fontSize: 12.5,
          fontWeight: active ? 700 : 500,
          background: active ? F.highlight : "transparent",
          color: active ? F.brand : F.text1,
        }}
        onMouseEnter={(e) => {
          if (!active) e.currentTarget.style.background = F.pageBg;
        }}
        onMouseLeave={(e) => {
          if (!active) e.currentTarget.style.background = "transparent";
        }}
      >
        <span
          style={{
            width: 16,
            textAlign: "center",
            color: active ? F.brand : F.text3,
          }}
        >
          {icon}
        </span>
        <span style={{ lineHeight: 1.25 }}>{label}</span>
      </button>
    );
  };

  const showEmptyShared = !searching && section === "shared";
  const showScheduledSection = section === "scheduled";
  const visibleScheduledReports = scheduledReports.filter(
    (item) =>
      !searching ||
      `${item.name} ${item.category} ${item.frequency} ${item.recipients}`
        .toLowerCase()
        .includes(search.trim().toLowerCase()),
  );
  const showEmptyFav =
    !searching && section === "favorites" && favorites.length === 0;

  const saveScheduledReport = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!scheduleReport) return;
    const recipients = [scheduleRecipients, ...scheduleAdditional.split(",")]
      .map((email) => email.trim())
      .filter(Boolean);
    if (!recipients.length) {
      toast("Enter at least one email recipient.", "error");
      return;
    }
    const hour = Math.min(12, Math.max(1, Number(scheduleHour) || 1));
    const minute = String(
      Math.min(59, Math.max(0, Number(scheduleMinute) || 0)),
    ).padStart(2, "0");
    setScheduledReports((prev) => [
      {
        id: `${scheduleReport.id}-${Date.now()}`,
        reportId: scheduleReport.id,
        name: scheduleReport.name,
        category: scheduleReport.category,
        frequency: scheduleFrequency,
        startDate: scheduleDate,
        time: `${String(hour).padStart(2, "0")}:${minute}`,
        recipients: recipients.join(", "),
        format: scheduleFormat,
      },
      ...prev,
    ]);
    toast(
      `${scheduleReport.name} scheduled ${scheduleFrequency.toLowerCase()} as ${scheduleFormat}.`,
      "success",
    );
    setScheduleReport(null);
  };

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 14,
        paddingTop: 16,
      }}
    >
      {scheduleReport && (
        <div
          role="presentation"
          onMouseDown={(e) => {
            if (e.target === e.currentTarget) setScheduleReport(null);
          }}
          style={{
            position: "fixed",
            inset: 0,
            zIndex: 1000,
            background: "rgba(15,23,42,0.48)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            padding: 20,
          }}
        >
          <section
            role="dialog"
            aria-modal="true"
            aria-label="Schedule Report"
            style={{
              width: "min(560px, 100%)",
              maxHeight: "90vh",
              overflowY: "auto",
              background: F.card,
              borderRadius: 8,
              boxShadow: "0 16px 48px rgba(0,0,0,0.25)",
            }}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "flex-start",
                padding: "20px 22px 14px",
                borderBottom: `1px solid ${F.border}`,
              }}
            >
              <div>
                <h2 style={{ margin: 0, fontSize: 19, color: F.text1 }}>
                  Schedule Report
                </h2>
                <div style={{ marginTop: 5, fontSize: 12, color: F.text2 }}>
                  Report Name: {scheduleReport.name}
                </div>
              </div>
              <button
                type="button"
                onClick={() => setScheduleReport(null)}
                aria-label="Close schedule report"
                style={{
                  border: 0,
                  background: "transparent",
                  color: F.text3,
                  fontSize: 22,
                  cursor: "pointer",
                }}
              >
                ×
              </button>
            </div>
            <form
              onSubmit={saveScheduledReport}
              style={{ padding: "18px 22px 22px" }}
            >
              <label
                style={{
                  display: "block",
                  fontSize: 12,
                  fontWeight: 700,
                  color: F.text2,
                  marginBottom: 14,
                }}
              >
                Frequency <span style={{ color: F.error }}>*</span>
                <select
                  required
                  value={scheduleFrequency}
                  onChange={(e) => setScheduleFrequency(e.target.value)}
                  style={{ ...iSt, display: "block", marginTop: 6 }}
                >
                  <option>Daily</option>
                  <option>Weekly</option>
                  <option>Monthly</option>
                  <option>Quarterly</option>
                </select>
              </label>
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "minmax(0,1fr) 90px 90px",
                  gap: 10,
                  marginBottom: 18,
                }}
              >
                <label
                  style={{ fontSize: 12, fontWeight: 700, color: F.text2 }}
                >
                  Start Date <span style={{ color: F.error }}>*</span>
                  <input
                    required
                    type="date"
                    value={scheduleDate}
                    onChange={(e) => setScheduleDate(e.target.value)}
                    style={{ ...iSt, display: "block", marginTop: 6 }}
                  />
                </label>
                <label
                  style={{ fontSize: 12, fontWeight: 700, color: F.text2 }}
                >
                  Hour
                  <input
                    type="number"
                    min="1"
                    max="12"
                    required
                    value={scheduleHour}
                    onChange={(e) => setScheduleHour(e.target.value)}
                    style={{ ...iSt, display: "block", marginTop: 6 }}
                  />
                </label>
                <label
                  style={{ fontSize: 12, fontWeight: 700, color: F.text2 }}
                >
                  Minutes
                  <input
                    type="number"
                    min="0"
                    max="59"
                    required
                    value={scheduleMinute}
                    onChange={(e) => setScheduleMinute(e.target.value)}
                    style={{ ...iSt, display: "block", marginTop: 6 }}
                  />
                </label>
              </div>
              <div
                style={{
                  borderTop: `1px solid ${F.border}`,
                  paddingTop: 16,
                  marginBottom: 14,
                  fontSize: 13,
                  fontWeight: 800,
                  color: F.text1,
                }}
              >
                Recipient Details
              </div>
              <label
                style={{
                  display: "block",
                  fontSize: 12,
                  fontWeight: 700,
                  color: F.text2,
                  marginBottom: 12,
                }}
              >
                Email Recipients <span style={{ color: F.error }}>*</span>
                <input
                  required
                  type="email"
                  placeholder="name@company.com"
                  value={scheduleRecipients}
                  onChange={(e) => setScheduleRecipients(e.target.value)}
                  style={{ ...iSt, display: "block", marginTop: 6 }}
                />
              </label>
              <label
                style={{
                  display: "block",
                  fontSize: 12,
                  fontWeight: 700,
                  color: F.text2,
                  marginBottom: 16,
                }}
              >
                Additional Recipients
                <input
                  type="text"
                  placeholder="Separate multiple email addresses with commas"
                  value={scheduleAdditional}
                  onChange={(e) => setScheduleAdditional(e.target.value)}
                  style={{ ...iSt, display: "block", marginTop: 6 }}
                />
              </label>
              <fieldset style={{ border: 0, padding: 0, margin: "0 0 20px" }}>
                <legend
                  style={{
                    fontSize: 12,
                    fontWeight: 700,
                    color: F.text2,
                    marginBottom: 8,
                  }}
                >
                  Attach Report <span style={{ color: F.error }}>*</span>
                </legend>
                {[
                  "PDF",
                  "XLS (Microsoft Excel 1997-2004 Compatible)",
                  "XLSX (Microsoft Excel)",
                ].map((format) => (
                  <label
                    key={format}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 8,
                      fontSize: 12,
                      margin: "7px 0",
                      color: F.text1,
                    }}
                  >
                    <input
                      type="radio"
                      name="scheduleFormat"
                      checked={scheduleFormat === format.split(" ")[0]}
                      onChange={() => setScheduleFormat(format.split(" ")[0])}
                    />
                    {format}
                  </label>
                ))}
              </fieldset>
              <div
                style={{
                  background: F.infoBg,
                  borderRadius: 6,
                  padding: 12,
                  fontSize: 11,
                  color: F.text2,
                  marginBottom: 18,
                }}
              >
                Note: The scheduled report uses the access permissions of the
                user who schedules it. Generated reports may be limited by
                system record limits.
              </div>
              <div
                style={{ display: "flex", justifyContent: "flex-end", gap: 8 }}
              >
                <Btn
                  variant="secondary"
                  onClick={() => setScheduleReport(null)}
                >
                  Cancel
                </Btn>
                <button
                  type="submit"
                  style={{
                    border: 0,
                    borderRadius: 5,
                    background: F.brand,
                    color: "#fff",
                    padding: "9px 16px",
                    fontWeight: 700,
                    cursor: "pointer",
                  }}
                >
                  Schedule
                </button>
              </div>
            </form>
          </section>
        </div>
      )}
      {/* Page header with search */}
      <div
        style={{
          background: F.card,
          border: `1px solid ${F.border}`,
          borderRadius: 8,
          padding: "16px 22px",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 16,
          flexWrap: "wrap",
          boxShadow: "0 1px 4px rgba(15,23,42,0.06)",
        }}
      >
        <h1
          style={{ margin: 0, fontSize: 20, fontWeight: 800, color: F.text1 }}
        >
          Reports Centre
        </h1>
        <div style={{ flex: "0 1 420px", minWidth: 240 }}>
          <input
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
            }}
            placeholder="Search reports (min. 3 characters)"
            style={{
              ...iSt,
              height: 36,
              borderColor: search ? F.brand : F.border,
            }}
          />
        </div>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "230px minmax(0, 1fr)",
          gap: 14,
          alignItems: "stretch",
          height: "calc(100vh - 230px)",
          minHeight: 420,
        }}
      >
        {/* Fixed (non-collapsible) category sidebar */}
        <div
          style={{
            background: F.card,
            border: `1px solid ${F.border}`,
            borderRadius: 8,
            padding: 8,
            boxShadow: "0 1px 3px rgba(0,0,0,0.03)",
            overflowY: "auto",
            minHeight: 0,
          }}
        >
          {sideItem("home", "Home", "⌂")}
          {sideItem("favorites", "Favorites", "☆")}
          {sideItem("shared", "Shared Reports", "⇄")}
          {sideItem("scheduled", "Scheduled Reports", "◷")}
          <div
            style={{
              fontSize: 10.5,
              fontWeight: 700,
              color: F.text3,
              letterSpacing: "0.08em",
              textTransform: "uppercase",
              padding: "14px 12px 6px",
            }}
          >
            Report Category
          </div>
          {RPT_CATEGORIES.map((c) => sideItem(c, c, "▭"))}
        </div>

        {/* Main list */}
        <div
          style={{
            background: F.card,
            border: `1px solid ${F.border}`,
            borderRadius: 8,
            overflow: "hidden",
            boxShadow: "0 1px 3px rgba(0,0,0,0.03)",
            display: "flex",
            flexDirection: "column",
            minHeight: 0,
          }}
        >
          <div
            style={{
              flexShrink: 0,
              padding: "14px 18px",
              borderBottom: `1px solid ${F.border}`,
              display: "flex",
              alignItems: "center",
              gap: 8,
            }}
          >
            <h2
              style={{
                margin: 0,
                fontSize: 15,
                fontWeight: 800,
                color: F.text1,
              }}
            >
              {listTitle}
            </h2>
            {!showEmptyShared && !showEmptyFav && (
              <span
                style={{
                  background: F.infoBg,
                  color: F.brand,
                  borderRadius: 10,
                  padding: "1px 8px",
                  fontSize: 11,
                  fontWeight: 800,
                }}
              >
                {showScheduledSection
                  ? visibleScheduledReports.length
                  : catalog.length}
              </span>
            )}
          </div>

          {search.trim().length > 0 && !searching && (
            <div
              style={{
                padding: "8px 18px",
                fontSize: 12,
                color: F.text3,
                background: F.infoBg,
              }}
            >
              Type at least 3 characters to search.
            </div>
          )}

          {showScheduledSection ? (
            visibleScheduledReports.length === 0 ? (
              emptyState(
                searching
                  ? "No scheduled reports match your search."
                  : "Currently, you don't have any scheduled reports.",
                searching
                  ? "Try another keyword."
                  : "Open any report and use the schedule icon to add it here.",
              )
            ) : (
              <div style={{ overflow: "auto", flex: 1, minHeight: 0 }}>
                <table style={{ width: "100%", borderCollapse: "collapse" }}>
                  <thead style={{ position: "sticky", top: 0, zIndex: 1 }}>
                    <tr>
                      <Th>Report Name</Th>
                      <Th>Report Category</Th>
                      <Th>Frequency</Th>
                      <Th>Start Date</Th>
                      <Th>Time</Th>
                      <Th>Recipients</Th>
                      <Th>Format</Th>
                    </tr>
                  </thead>
                  <tbody>
                    {visibleScheduledReports.map((item) => (
                      <TrH
                        key={item.id}
                        onClick={() => {
                          const report = REPORTS.find(
                            (r) => r.id === item.reportId,
                          );
                          if (report) openReport(report);
                        }}
                      >
                        <Td>
                          <span style={{ color: F.brand, fontWeight: 600 }}>
                            {item.name}
                          </span>
                        </Td>
                        <Td>{item.category}</Td>
                        <Td>{item.frequency}</Td>
                        <Td>{item.startDate}</Td>
                        <Td>{item.time}</Td>
                        <Td>{item.recipients}</Td>
                        <Td>{item.format}</Td>
                      </TrH>
                    ))}
                  </tbody>
                </table>
              </div>
            )
          ) : showEmptyShared ? (
            emptyState(
              "Currently, you don't have any shared reports.",
              "If someone shares a report with you, you will be able to view it here.",
            )
          ) : showEmptyFav ? (
            emptyState(
              "You haven't marked any reports as favorite.",
              "Click the star icon next to a report to view it here.",
            )
          ) : catalog.length === 0 ? (
            emptyState(
              "No reports match your search.",
              "Try a different keyword or category.",
            )
          ) : (
            <>
              <div style={{ overflow: "auto", flex: 1, minHeight: 0 }}>
                <table style={{ width: "100%", borderCollapse: "collapse" }}>
                  <thead style={{ position: "sticky", top: 0, zIndex: 1 }}>
                    <tr>
                      <Th>Report Name</Th>
                      <Th>Report Category</Th>
                      <Th>Created By</Th>
                      <Th>Last Visited</Th>
                    </tr>
                  </thead>
                  <tbody>
                    {pagedCatalog.map((r) => {
                      const fav = favorites.includes(r.id);
                      return (
                        <TrH key={r.id} onClick={() => openReport(r)}>
                          <Td>
                            <div
                              style={{
                                display: "flex",
                                alignItems: "center",
                                gap: 8,
                              }}
                            >
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  toggleFavorite(r.id);
                                }}
                                title={
                                  fav
                                    ? "Remove from favorites"
                                    : "Add to favorites"
                                }
                                aria-label={
                                  fav
                                    ? "Remove from favorites"
                                    : "Add to favorites"
                                }
                                style={{
                                  border: "none",
                                  background: "transparent",
                                  cursor: "pointer",
                                  fontSize: 14,
                                  color: fav ? F.warning : F.text3,
                                  padding: 0,
                                }}
                              >
                                {fav ? "★" : "☆"}
                              </button>
                              <span style={{ color: F.brand, fontWeight: 600 }}>
                                {r.name}
                              </span>
                            </div>
                          </Td>
                          <Td>{r.category}</Td>
                          <Td>System Generated</Td>
                          <Td>{lastVisited[r.id] ?? "-"}</Td>
                        </TrH>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

function AccessManagementView({ emps }: { emps: Employee[] }) {
  const toast = useToast()
  const [accessTab, setAccessTab] = useState<"users" | "roles">("users")
  const [roles, setRoles] = useState<AccessRole[]>(loadRoles)
  const roleOptions = [
    "Org Admin",
    "Employee",
    ...roles.filter((role) => role.id !== "admin").map((role) => role.name),
  ]
  const roleScope = (role: string) =>
    role === "Org Admin"
      ? "Full Admin Access"
      : role === "Employee"
        ? "Self-Service Only"
        : `Role: ${role}`

  const [users, setUsers] = useState<AccessUser[]>(() => {
    try {
      const saved = JSON.parse(localStorage.getItem(USER_STORAGE) || "null")
      if (
        Array.isArray(saved) &&
        saved.every(
          (user) =>
            user &&
            typeof user.name === "string" &&
            typeof user.role === "string" &&
            ["Active", "Locked"].includes(user.status),
        )
      ) {
        return saved.map((user, index) => ({
          ...user,
          id:
            user.id ||
            `access-user-${index}-${user.name
              .toLowerCase()
              .replace(/[^a-z0-9]+/g, "-")}`,
          email:
            user.email ||
            emps.find((employee) => employee.name === user.name)?.email ||
            `${user.name
              .toLowerCase()
              .replace(/[^a-z0-9]+/g, ".")}@PayrollGuard AI.com`,
        }))
      }
    } catch {
      // Use the application roster when stored user data is unavailable.
    }

    return [
      {
        id: "access-admin-meena-iyer",
        name: "Meena Iyer",
        email:
          emps.find((employee) => employee.name === "Meena Iyer")?.email ||
          "meena.iyer@PayrollGuard AI.com",
        role: "Org Admin",
        status: "Active",
        department: "Executive & Admin",
        scope: "Full Admin Access",
        isOrganizationAdmin: true,
      },
      ...emps
        .filter((employee) => employee.id !== "EMP-003")
        .map((employee) => ({
          id: `access-${employee.id.toLowerCase()}`,
          name: employee.name,
          email: employee.email,
          role: "Employee",
          status:
            employee.id === "EMP-006"
              ? ("Locked" as const)
              : ("Active" as const),
          department: employee.department || "Operations",
          scope: "Self-Service Only",
        })),
    ]
  })

  useEffect(() => {
    try {
      localStorage.setItem(USER_STORAGE, JSON.stringify(users))
    } catch {
      toast("User changes could not be saved in this browser.", "error")
    }
  }, [users])

  const assignedCount = (role: AccessRole) =>
    users.filter(
      (user) =>
        user.role === (role.id === "admin" ? "Org Admin" : role.name),
    ).length

  const saveRole = (role: AccessRole) => {
    const previous = roles.find((item) => item.id === role.id)
    if (previous?.builtin) return false

    const nextRoles = previous
      ? roles.map((item) => (item.id === role.id ? role : item))
      : [...roles, role]
    const nextUsers = previous
      ? users.map((user) =>
          user.role === previous.name
            ? { ...user, role: role.name, scope: roleScope(role.name) }
            : user,
        )
      : users

    try {
      localStorage.setItem(
        ROLE_STORAGE,
        JSON.stringify(nextRoles.filter((item) => !item.builtin)),
      )
      localStorage.setItem(USER_STORAGE, JSON.stringify(nextUsers))
    } catch {
      toast("Unable to save this role. Check browser storage and try again.", "error")
      return false
    }

    setRoles(nextRoles)
    setUsers(nextUsers)
    toast("Role saved successfully", "success")
    return true
  }

  const deleteRole = (role: AccessRole) => {
    if (role.builtin) return false
    if (assignedCount(role)) {
      toast("Reassign all users before deleting this role.", "error")
      return false
    }

    const nextRoles = roles.filter((item) => item.id !== role.id)
    try {
      localStorage.setItem(
        ROLE_STORAGE,
        JSON.stringify(nextRoles.filter((item) => !item.builtin)),
      )
    } catch {
      toast("Unable to delete this role from browser storage.", "error")
      return false
    }

    setRoles(nextRoles)
    toast("Role deleted", "success")
    return true
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 18 }}>
      <PH
        title="Access Management & Roles"
        sub="Configure user accounts, role assignments, and security permissions"
      />

      <div
        role="tablist"
        aria-label="Access management"
        style={{
          display: "flex",
          gap: 4,
          borderBottom: `1px solid ${F.border}`,
        }}
      >
        {(["users", "roles"] as const).map((tab) => (
          <button
            key={tab}
            id={`access-tab-${tab}`}
            role="tab"
            aria-selected={accessTab === tab}
            aria-controls={`access-panel-${tab}`}
            onClick={() => setAccessTab(tab)}
            style={{
              padding: "12px 22px",
              border: "none",
              borderBottom: `3px solid ${
                accessTab === tab ? F.brand : "transparent"
              }`,
              background: "transparent",
              color: accessTab === tab ? F.brand : F.text2,
              fontWeight: 700,
              cursor: "pointer",
              fontFamily: "inherit",
            }}
          >
            {tab === "users"
              ? `Users (${users.length})`
              : `Roles (${roles.length})`}
          </button>
        ))}
      </div>

      <div
        id="access-panel-roles"
        role="tabpanel"
        aria-labelledby="access-tab-roles"
        hidden={accessTab !== "roles"}
      >
        <AccessRoles
          roles={roles}
          onSave={saveRole}
          onDelete={deleteRole}
          assignedCount={assignedCount}
        />
      </div>

      {accessTab === "users" && (
        <div
          id="access-panel-users"
          role="tabpanel"
          aria-labelledby="access-tab-users"
        >
          <AccessUsers
            users={users}
            roles={roles}
            roleOptions={roleOptions}
            roleScope={roleScope}
            onChange={setUsers}
            notify={toast}
          />
        </div>
      )}
    </div>
  )
}
function AuditHistoryView({
  logs,
  errorLogs = [],
}: {
  logs: AuditLog[]
  errorLogs?: ErrorLog[]
}) {
  const toast = useToast()
  const [tab, setTab] = useState<"audit" | "errors">("audit")
  const [auditPage, setAuditPage] = useState(1)
  const [hasRunAuditSearch, setHasRunAuditSearch] = useState(false)
  const [filterDraft, setFilterDraft] = useState({
    search: "",
    module: "All",
    user: "All",
    dateFrom: "",
    dateTo: "",
    severity: "All",
    status: "All",
  })
  const [appliedFilters, setAppliedFilters] = useState(filterDraft)
  const activeRows = tab === "audit" ? logs : errorLogs
  const modules = ["All", ...Array.from(new Set(activeRows.map((a) => a.module)))]
  const users = ["All", ...Array.from(new Set(activeRows.map((a) => a.user)))]
  const withinDate = (timestamp: string) => {
    const day = timestamp.slice(0, 10)
    return (
      (!appliedFilters.dateFrom || day >= appliedFilters.dateFrom) &&
      (!appliedFilters.dateTo || day <= appliedFilters.dateTo)
    )
  }
  const filtered = logs.filter(
    (a) =>
      (appliedFilters.module === "All" || a.module === appliedFilters.module) &&
      (appliedFilters.user === "All" || a.user === appliedFilters.user) &&
      withinDate(a.timestamp) &&
      searchMatches(appliedFilters.search, [a.action, a.user, a.module, a.oldValue, a.newValue]),
  )
  const filteredErrors = errorLogs.filter(
    (a) =>
      (appliedFilters.module === "All" || a.module === appliedFilters.module) &&
      (appliedFilters.user === "All" || a.user === appliedFilters.user) &&
      (appliedFilters.severity === "All" || a.severity === appliedFilters.severity) &&
      (appliedFilters.status === "All" || a.status === appliedFilters.status) &&
      withinDate(a.timestamp) &&
      searchMatches(appliedFilters.search, [a.issue, a.user, a.module, a.route, a.status, a.severity]),
  )
  const activeFilteredRows = hasRunAuditSearch ? (tab === "audit" ? filtered : filteredErrors) : []
  const visibleAuditRows = hasRunAuditSearch
    ? filtered.slice((auditPage - 1) * 10, auditPage * 10)
    : []
  const visibleErrorRows = hasRunAuditSearch
    ? filteredErrors.slice((auditPage - 1) * 10, auditPage * 10)
    : []
  const clearFilters = () => {
    setHasRunAuditSearch(false)
    const empty = {
      search: "",
      module: "All",
      user: "All",
      dateFrom: "",
      dateTo: "",
      severity: "All",
      status: "All",
    }
    setFilterDraft(empty)
    setAppliedFilters(empty)
    toast("Filters cleared", "info")
  }
  const applyFilters = () => {
    setHasRunAuditSearch(true)
    setAuditPage(1)
    setAppliedFilters(filterDraft)
    toast("Filters applied", "success")
  }
  const activeFilterCount =
    (activeSearch(appliedFilters.search) ? 1 : 0) +
    (appliedFilters.module !== "All" ? 1 : 0) +
    (appliedFilters.user !== "All" ? 1 : 0) +
    (appliedFilters.dateFrom ? 1 : 0) +
    (appliedFilters.dateTo ? 1 : 0) +
    (tab === "errors" && appliedFilters.severity !== "All" ? 1 : 0) +
    (tab === "errors" && appliedFilters.status !== "All" ? 1 : 0)
  return (
    <div>
      <PH
        title="Audit & Error Logs"
        sub="Role-scoped tracking for sensitive activity, broken flows, and operational issues"
        action={
          <Btn
            variant="secondary"
            onClick={() =>
              toast(
                tab === "audit"
                  ? "Audit log exported as CSV"
                  : "Error log exported as CSV",
                "success",
              )
            }
          >
            Export {tab === "audit" ? "Audit" : "Errors"}
          </Btn>
        }
      />
      <TabBar
        tabs={[
          { id: "audit", label: "Audit History" },
          { id: "errors", label: "Error Logs" },
        ]}
        active={tab}
        onSelect={(id) => {
          setTab(id as "audit" | "errors")
          clearFilters()
        }}
      />
      <div
        style={{
          background: F.card,
          border: `1px solid ${F.border}`,
          borderRadius: 8,
          padding: 14,
          marginBottom: 14,
          display: "grid",
          gridTemplateColumns: "minmax(260px, 1.6fr) repeat(4, minmax(130px, 1fr))",
          gap: 10,
          alignItems: "end",
        }}
      >
        <Fld label={tab === "audit" ? "Search Audit Trail" : "Search Error Details"}>
        <input
          value={filterDraft.search}
          onChange={(e) => setFilterDraft({ ...filterDraft, search: e.target.value })}
          placeholder={
            tab === "audit"
              ? "Search action, user, or module (min 3 chars)..."
              : "Search issue, user, route, or module (min 3 chars)..."
          }
          style={iSt}
        />
        </Fld>
        <Fld label="Module">
        <select
          value={filterDraft.module}
          onChange={(e) => setFilterDraft({ ...filterDraft, module: e.target.value })}
          style={iSt}
        >
          {modules.map((m) => (
            <option key={m}>{m}</option>
          ))}
        </select>
        </Fld>
        <Fld label="User">
        <select
          value={filterDraft.user}
          onChange={(e) => setFilterDraft({ ...filterDraft, user: e.target.value })}
          style={iSt}
        >
          {users.map((u) => (
            <option key={u}>{u}</option>
          ))}
        </select>
        </Fld>
        <Fld label="Record Date From">
          <StrictDateInput
            ariaLabel="Record date from"
            value={filterDraft.dateFrom}
            onChange={(value) => setFilterDraft({ ...filterDraft, dateFrom: value })}
            style={iSt}
          />
        </Fld>
        <Fld label="Record Date To">
          <StrictDateInput
            ariaLabel="Record date to"
            value={filterDraft.dateTo}
            onChange={(value) => setFilterDraft({ ...filterDraft, dateTo: value })}
            style={iSt}
          />
        </Fld>
        {tab === "errors" && (
          <>
            <Fld label="Severity">
              <select
                value={filterDraft.severity}
                onChange={(e) => setFilterDraft({ ...filterDraft, severity: e.target.value })}
                style={iSt}
              >
                <option>All</option>
                <option>Critical</option>
                <option>High</option>
                <option>Medium</option>
                <option>Low</option>
              </select>
            </Fld>
            <Fld label="Status">
              <select
                value={filterDraft.status}
                onChange={(e) => setFilterDraft({ ...filterDraft, status: e.target.value })}
                style={iSt}
              >
                <option>All</option>
                <option>Open</option>
                <option>Investigating</option>
                <option>Resolved</option>
              </select>
            </Fld>
          </>
        )}
        <div style={{ display: "flex", gap: 8, justifyContent: "flex-end", gridColumn: "1 / -1" }}>
          <Btn onClick={applyFilters}>Go</Btn>
          <Btn variant="secondary" onClick={clearFilters}>Clear Filters</Btn>
        </div>
      </div>
      {activeFilterCount > 0 && (
        <div style={{ marginBottom: 12, fontSize: 12, color: F.text2, fontWeight: 700 }}>
          Showing filtered results - {activeFilterCount} active filter{activeFilterCount !== 1 ? "s" : ""}
        </div>
      )}
      {tab === "audit" ? (
        <div
        style={{
          background: F.card,
          border: `1px solid ${F.border}`,
          borderRadius: 8,
          overflow: "hidden",
        }}
      >
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <Th>Timestamp</Th>
              <Th>User</Th>
              <Th>Module</Th>
              <Th>Action</Th>
              <Th>Old Value</Th>
              <Th>New Value</Th>
            </tr>
          </thead>
          <tbody>
            {visibleAuditRows.length === 0 && (
              <tr>
                <td
                  colSpan={6}
                  style={{
                    padding: 32,
                    textAlign: "center",
                    color: F.text3,
                    fontSize: 13,
                  }}
                >
                  {hasRunAuditSearch ? "No matching audit events." : "Select filters and click Go to load audit events."}
                </td>
              </tr>
            )}
            {visibleAuditRows.map((a) => (
              <TrH key={a.id}>
                <Td mono>
                  <span style={{ fontSize: 11, color: F.text2 }}>
                    {a.timestamp}
                  </span>
                </Td>
                <Td>
                  <span style={{ fontWeight: 600 }}>{a.user}</span>
                </Td>
                <Td>
                  <Badge label={a.module} color={F.brand} bg={F.infoBg} />
                </Td>
                <Td>
                  <span style={{ fontSize: 12, fontWeight: 500 }}>
                    {a.action}
                  </span>
                </Td>
                <Td>
                  <span
                    style={{
                      fontSize: 11,
                      color: F.text3,
                      fontFamily: "'JetBrains Mono',monospace",
                    }}
                  >
                    {a.oldValue}
                  </span>
                </Td>
                <Td>
                  <span
                    style={{
                      fontSize: 11,
                      color: F.success,
                      fontFamily: "'JetBrains Mono',monospace",
                    }}
                  >
                    {a.newValue}
                  </span>
                </Td>
              </TrH>
            ))}
          </tbody>
        </table>
        </div>
      ) : (
        <div
          style={{
            background: F.card,
            border: `1px solid ${F.border}`,
            borderRadius: 8,
            overflow: "hidden",
          }}
        >
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                <Th>Timestamp</Th>
                <Th>User</Th>
                <Th>Module</Th>
                <Th>Severity</Th>
                <Th>Issue</Th>
                <Th>Status</Th>
              </tr>
            </thead>
            <tbody>
              {visibleErrorRows.length === 0 && (
                <tr>
                  <td
                    colSpan={6}
                    style={{
                      padding: 32,
                      textAlign: "center",
                      color: F.text3,
                      fontSize: 13,
                    }}
                  >
                    {hasRunAuditSearch ? "No matching error events." : "Select filters and click Go to load error events."}
                  </td>
                </tr>
              )}
              {visibleErrorRows.map((a) => (
                <TrH key={a.id}>
                  <Td mono>
                    <span style={{ fontSize: 11, color: F.text2 }}>
                      {a.timestamp}
                    </span>
                  </Td>
                  <Td>
                    <span style={{ fontWeight: 600 }}>{a.user}</span>
                    <div style={{ fontSize: 11, color: F.text3 }}>{a.id}</div>
                  </Td>
                  <Td>
                    <Badge label={a.module} color={F.brand} bg={F.infoBg} />
                  </Td>
                  <Td>
                    <Badge
                      label={a.severity}
                      color={
                        a.severity === "Critical" || a.severity === "High"
                          ? F.error
                          : a.severity === "Medium"
                            ? F.warning
                            : F.text2
                      }
                      bg={
                        a.severity === "Critical" || a.severity === "High"
                          ? F.errorBg
                          : a.severity === "Medium"
                            ? F.warningBg
                            : F.pageBg
                      }
                    />
                  </Td>
                  <Td>
                    <span style={{ fontSize: 12, fontWeight: 500 }}>
                      {a.issue}
                    </span>
                    <div style={{ fontSize: 11, color: F.text3, marginTop: 3 }}>
                      {a.route}
                    </div>
                  </Td>
                  <Td>
                    <Badge
                      label={a.status}
                      color={a.status === "Resolved" ? F.success : F.warning}
                      bg={a.status === "Resolved" ? F.successBg : F.warningBg}
                    />
                  </Td>
                </TrH>
              ))}
            </tbody>
          </table>
          <Pagination page={auditPage} pageSize={10} total={activeFilteredRows.length} onPageChange={setAuditPage} />
        </div>
      )}
    </div>
  )
}

